pub struct SqlAuditEntryRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlAuditEntryRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl AuditEntryRepository for SqlAuditEntryRepository<'_> {
    async fn find_by_entry_no(&self, entry_no: i32) -> Result<Option<AuditEntry>, DomainError> {
        let query = statement(format!("SELECT {COLUMNS} FROM `audit_entries` WHERE `entry_no` = ?")).bind(entry_no);
        let row = self.db.one(query).await?;
        Ok(row.as_ref().map(to_entity).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<AuditEntry>, DomainError> {
        let query = statement(format!("SELECT {COLUMNS} FROM `audit_entries` ORDER BY `entry_no` LIMIT ? OFFSET ?")).bind(limit as i64).bind(offset as i64);
        let items = to_entities(self.db.all(query).await?)?;
        let count = self.db.one(statement("SELECT COUNT(*) FROM `audit_entries`")).await?.ok_or(sqlx::Error::RowNotFound)?;
        let total = count.try_get::<i64, _>(0)? as u64;
        Ok(Page { items, total, offset, limit })
    }

    async fn list_by_order_id(&self, order_id: i64) -> Result<Vec<AuditEntry>, DomainError> {
        let query = statement(format!("SELECT {COLUMNS} FROM `audit_entries` WHERE `orderId` = ? ORDER BY `entry_no`")).bind(order_id);
        Ok(to_entities(self.db.all(query).await?)?)
    }

    async fn insert(&self, entity: AuditEntry) -> Result<AuditEntry, DomainError> {
        let mut entity = entity;
        let mut given = Vec::new();
        if entity.entry_no.is_some() {
            given.push("`entry_no`");
        }
        if entity.order_id.is_some() {
            given.push("`orderId`");
        }
        if entity.message.is_some() {
            given.push("`message`");
        }
        let sql = insert_sql("`audit_entries`", &given);
        let mut query = statement(sql);
        if let Some(value) = entity.entry_no {
            query = query.bind(value);
        }
        if let Some(value) = entity.order_id {
            query = query.bind(value);
        }
        if let Some(value) = entity.message.clone() {
            query = query.bind(value);
        }
        let result = self.db.run(query).await.map_err(refused)?;
        entity.entry_no = entity.entry_no.or(Some(result.last_insert_id() as i32));
        let query = statement(format!("SELECT {COLUMNS} FROM `audit_entries` WHERE `entry_no` = ?")).bind(entity.entry_no.expect("entry_no is set"));
        let row = self.db.one(query).await?.ok_or(sqlx::Error::RowNotFound)?;
        Ok(to_entity(&row)?)
    }

    async fn update(&self, entity: AuditEntry) -> Result<AuditEntry, DomainError> {
        let query = statement("UPDATE `audit_entries` SET `orderId` = ?, `message` = ? WHERE `entry_no` = ?").bind(entity.order_id).bind(entity.message.clone()).bind(entity.entry_no.expect("entry_no is set"));
        self.db.run(query).await.map_err(refused)?;
        let query = statement(format!("SELECT {COLUMNS} FROM `audit_entries` WHERE `entry_no` = ?")).bind(entity.entry_no.expect("entry_no is set"));
        let row = self.db.one(query).await?.ok_or(sqlx::Error::RowNotFound)?;
        Ok(to_entity(&row)?)
    }

    async fn delete(&self, entity: &AuditEntry) -> Result<(), DomainError> {
        let query = statement("DELETE FROM `audit_entries` WHERE `entry_no` = ?").bind(entity.entry_no.expect("entry_no is set"));
        self.db.run(query).await.map_err(refused)?;
        Ok(())
    }
}

/// The columns every read selects.
const COLUMNS: &str = "`entry_no`, `orderId`, `message`";

/// The entity of a row read with COLUMNS.
fn to_entity(row: &DbRow) -> Result<AuditEntry, sqlx::Error> {
    Ok(AuditEntry {
        entry_no: row.try_get_unchecked::<Option<i32>, _>(0)?,
        order_id: row.try_get_unchecked::<Option<i64>, _>(1)?,
        message: row.try_get_unchecked::<Option<String>, _>(2)?,
    })
}

/// The entities of the rows read with COLUMNS.
fn to_entities(rows: Vec<DbRow>) -> Result<Vec<AuditEntry>, sqlx::Error> {
    rows.iter().map(to_entity).collect()
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: sqlx::Error) -> DomainError {
    if error.as_database_error().is_some_and(|refusal| !matches!(refusal.kind(), ErrorKind::Other)) {
        DomainError::conflict("AuditEntry", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps audit_entries rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryAuditEntryRepository {
    rows: Arc<Mutex<Vec<AuditEntry>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryAuditEntryRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<AuditEntry> {
        let mut rows: Vec<AuditEntry> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &AuditEntry) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &AuditEntry) -> (Option<i32>,) {
    (row.entry_no,)
}

#[async_trait]
impl AuditEntryRepository for MemoryAuditEntryRepository {
    async fn find_by_entry_no(&self, entry_no: i32) -> Result<Option<AuditEntry>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.entry_no.as_ref() == Some(&entry_no)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<AuditEntry>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn list_by_order_id(&self, order_id: i64) -> Result<Vec<AuditEntry>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.order_id.as_ref() == Some(&order_id)).collect())
    }

    async fn insert(&self, entity: AuditEntry) -> Result<AuditEntry, DomainError> {
        let mut entity = entity;
        entity.entry_no = entity.entry_no.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next as i32)
        });
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: AuditEntry) -> Result<AuditEntry, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &AuditEntry) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

