//! The repositories of the "kinds" table. Repositories decide nothing.

use async_trait::async_trait;
use crate::common::Page;
use crate::database::{Db, DbRow, insert_sql, statement};
use crate::entities::kind::Kind;
use crate::errors::DomainError;
use sqlx::Row;
use sqlx::error::ErrorKind;
use std::cmp::Ordering;
use std::sync::{Arc, Mutex};

/// Where kinds rows are kept. Services depend only on this trait.
#[async_trait]
pub trait KindRepository: Send + Sync {
    /// The row with this primary key, or None.
    async fn find_by_code_and_day(&self, code: String, day: chrono::NaiveDate) -> Result<Option<Kind>, DomainError>;

    /// At most limit rows from offset, by primary key, and how many there are.
    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Kind>, DomainError>;

    /// Stores a new row; the values the database fills are read back.
    async fn insert(&self, entity: Kind) -> Result<Kind, DomainError>;

    /// Stores the changes made to a row.
    async fn update(&self, entity: Kind) -> Result<Kind, DomainError>;

    /// Removes a row.
    async fn delete(&self, entity: &Kind) -> Result<(), DomainError>;
}

/// Keeps kinds rows in the database, through sqlx: on the connection of the unit of work, or in its transaction.
pub struct SqlKindRepository<'a> {
    db: &'a Db,
}

impl<'a> SqlKindRepository<'a> {
    pub fn new(db: &'a Db) -> Self {
        Self { db }
    }
}

#[async_trait]
impl KindRepository for SqlKindRepository<'_> {
    async fn find_by_code_and_day(&self, code: String, day: chrono::NaiveDate) -> Result<Option<Kind>, DomainError> {
        let query = statement(format!("SELECT {COLUMNS} FROM `kinds` WHERE `code` = ? AND `day` = ?")).bind(code).bind(day);
        let row = self.db.one(query).await?;
        Ok(row.as_ref().map(to_entity).transpose()?)
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Kind>, DomainError> {
        let query = statement(format!("SELECT {COLUMNS} FROM `kinds` ORDER BY `code`, `day` LIMIT ? OFFSET ?")).bind(limit as i64).bind(offset as i64);
        let items = to_entities(self.db.all(query).await?)?;
        let count = self.db.one(statement("SELECT COUNT(*) FROM `kinds`")).await?.ok_or(sqlx::Error::RowNotFound)?;
        let total = count.try_get::<i64, _>(0)? as u64;
        Ok(Page { items, total, offset, limit })
    }

    async fn insert(&self, entity: Kind) -> Result<Kind, DomainError> {
        let mut given = Vec::new();
        if entity.code.is_some() {
            given.push("`code`");
        }
        if entity.day.is_some() {
            given.push("`day`");
        }
        if entity.label.is_some() {
            given.push("`label`");
        }
        let sql = insert_sql("`kinds`", &given);
        let mut query = statement(sql);
        if let Some(value) = entity.code.clone() {
            query = query.bind(value);
        }
        if let Some(value) = entity.day {
            query = query.bind(value);
        }
        if let Some(value) = entity.label.clone() {
            query = query.bind(value);
        }
        self.db.run(query).await.map_err(refused)?;
        let query = statement(format!("SELECT {COLUMNS} FROM `kinds` WHERE `code` = ? AND `day` = ?")).bind(entity.code.clone().expect("code is set")).bind(entity.day.expect("day is set"));
        let row = self.db.one(query).await?.ok_or(sqlx::Error::RowNotFound)?;
        Ok(to_entity(&row)?)
    }

    async fn update(&self, entity: Kind) -> Result<Kind, DomainError> {
        let query = statement("UPDATE `kinds` SET `label` = ? WHERE `code` = ? AND `day` = ?").bind(entity.label.clone()).bind(entity.code.clone().expect("code is set")).bind(entity.day.expect("day is set"));
        self.db.run(query).await.map_err(refused)?;
        let query = statement(format!("SELECT {COLUMNS} FROM `kinds` WHERE `code` = ? AND `day` = ?")).bind(entity.code.clone().expect("code is set")).bind(entity.day.expect("day is set"));
        let row = self.db.one(query).await?.ok_or(sqlx::Error::RowNotFound)?;
        Ok(to_entity(&row)?)
    }

    async fn delete(&self, entity: &Kind) -> Result<(), DomainError> {
        let query = statement("DELETE FROM `kinds` WHERE `code` = ? AND `day` = ?").bind(entity.code.clone().expect("code is set")).bind(entity.day.expect("day is set"));
        self.db.run(query).await.map_err(refused)?;
        Ok(())
    }
}

/// The columns every read selects.
const COLUMNS: &str = "`code`, `day`, `label`";

/// The entity of a row read with COLUMNS.
fn to_entity(row: &DbRow) -> Result<Kind, sqlx::Error> {
    Ok(Kind {
        code: row.try_get_unchecked::<Option<String>, _>(0)?,
        day: row.try_get_unchecked::<Option<chrono::NaiveDate>, _>(1)?,
        label: row.try_get_unchecked::<Option<String>, _>(2)?,
    })
}

/// The entities of the rows read with COLUMNS.
fn to_entities(rows: Vec<DbRow>) -> Result<Vec<Kind>, sqlx::Error> {
    rows.iter().map(to_entity).collect()
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: sqlx::Error) -> DomainError {
    if error.as_database_error().is_some_and(|refusal| !matches!(refusal.kind(), ErrorKind::Other)) {
        DomainError::conflict("Kind", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps kinds rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryKindRepository {
    rows: Arc<Mutex<Vec<Kind>>>,
}

impl MemoryKindRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Kind> {
        let mut rows: Vec<Kind> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Kind) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Kind) -> (Option<String>, Option<chrono::NaiveDate>) {
    (row.code.clone(), row.day)
}

#[async_trait]
impl KindRepository for MemoryKindRepository {
    async fn find_by_code_and_day(&self, code: String, day: chrono::NaiveDate) -> Result<Option<Kind>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.code.as_ref() == Some(&code) && row.day.as_ref() == Some(&day)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Kind>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn insert(&self, entity: Kind) -> Result<Kind, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Kind) -> Result<Kind, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Kind) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

