/// The columns every read selects.
const COLUMNS: &str = "`id`, `tiny`, `small`, `medium`, `num`, `big`, `price`, `r`, `d`, `flag`, `born`, `opens`, `at`, `at_ts`, `changed`, `bin`, `blobby`, `data`, `feeling`, `code`, `note`, `long_note`, `total`";

/// The entity of a row read with COLUMNS.
fn to_entity(row: &DbRow) -> Result<Thing, sqlx::Error> {
    Ok(Thing {
        id: row.try_get_unchecked::<Option<Vec<u8>>, _>(0)?,
        tiny: row.try_get_unchecked::<Option<i16>, _>(1)?,
        small: row.try_get_unchecked::<Option<i16>, _>(2)?,
        medium: row.try_get_unchecked::<Option<i32>, _>(3)?,
        num: row.try_get_unchecked::<Option<i32>, _>(4)?,
        big: row.try_get_unchecked::<Option<i64>, _>(5)?,
        price: row.try_get_unchecked::<Option<rust_decimal::Decimal>, _>(6)?,
        r: row.try_get_unchecked::<Option<f32>, _>(7)?,
        d: row.try_get_unchecked::<Option<f64>, _>(8)?,
        flag: row.try_get_unchecked::<Option<bool>, _>(9)?,
        born: row.try_get_unchecked::<Option<chrono::NaiveDate>, _>(10)?,
        opens: row.try_get_unchecked::<Option<chrono::NaiveTime>, _>(11)?,
        at: row.try_get_unchecked::<Option<chrono::NaiveDateTime>, _>(12)?,
        at_ts: row.try_get_unchecked::<Option<chrono::NaiveDateTime>, _>(13)?,
        changed: row.try_get_unchecked::<Option<chrono::NaiveDateTime>, _>(14)?,
        bin: row.try_get_unchecked::<Option<Vec<u8>>, _>(15)?,
        blobby: row.try_get_unchecked::<Option<Vec<u8>>, _>(16)?,
        data: row.try_get_unchecked::<Option<String>, _>(17)?,
        feeling: row.try_get_unchecked::<Option<String>, _>(18)?,
        code: row.try_get_unchecked::<Option<String>, _>(19)?,
        note: row.try_get_unchecked::<Option<String>, _>(20)?,
        long_note: row.try_get_unchecked::<Option<String>, _>(21)?,
        total: row.try_get_unchecked::<Option<rust_decimal::Decimal>, _>(22)?,
    })
}

/// The entities of the rows read with COLUMNS.
fn to_entities(rows: Vec<DbRow>) -> Result<Vec<Thing>, sqlx::Error> {
    rows.iter().map(to_entity).collect()
}

/// A refusal of the database (a unique value, a row still pointed to) becomes a Conflict.
fn refused(error: sqlx::Error) -> DomainError {
    if error.as_database_error().is_some_and(|refusal| !matches!(refusal.kind(), ErrorKind::Other)) {
        DomainError::conflict("Thing", &format!("the database refused the change: {error}"), &[])
    } else {
        error.into()
    }
}

/// Keeps things rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryThingRepository {
    rows: Arc<Mutex<Vec<Thing>>>,
}

impl MemoryThingRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Thing> {
        let mut rows: Vec<Thing> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Thing) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Thing) -> (Option<Vec<u8>>,) {
    (row.id.clone(),)
}

#[async_trait]
impl ThingRepository for MemoryThingRepository {
    async fn find_by_id(&self, id: Vec<u8>) -> Result<Option<Thing>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Thing>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn insert(&self, entity: Thing) -> Result<Thing, DomainError> {
        let mut entity = entity;
        entity.flag = entity.flag.or_else(|| Some(true));
        entity.at_ts = entity.at_ts.or_else(|| Some(chrono::Utc::now().naive_utc()));
        entity.changed = entity.changed.or_else(|| Some(chrono::Utc::now().naive_utc()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Thing) -> Result<Thing, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Thing) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

