/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    order_id: Option<Option<i64>>,
    message: Option<Option<String>>,
}

/// Checks the values against the rules of the "audit_entries" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&AuditEntry>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.order_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.order_id.is_some() {
                errors.push(FieldError::new("orderId", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.message.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.message.is_some() {
                errors.push(FieldError::new("message", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 200 {
                errors.push(FieldError::new("message", "is longer than 200 characters"));
            }
        }
    }
    {
        let order_id = values.order_id.clone().unwrap_or_else(|| current.and_then(|current| current.order_id));
        if let Some(order_id) = order_id {
            if uow.order().find_by_id(order_id).await?.is_none() {
                errors.push(FieldError::new("orderId", "no Order has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "AuditEntry".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&AuditEntry>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut AuditEntry, values: &Values) {
    if let Some(value) = &values.order_id {
        entity.order_id = *value;
    }
    if let Some(value) = &values.message {
        entity.message = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: AuditEntryChanges) -> Values {
    Values { order_id: changes.order_id.given(), message: changes.message.given() }
}

/// The AuditEntry with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, entry_no: i32) -> Result<AuditEntry, DomainError> {
    uow.audit_entries().find_by_entry_no(entry_no).await?.ok_or_else(|| DomainError::not_found("AuditEntry", entry_no))
}

