                errors.push(FieldError::new("opens", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.at.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.at.is_some() {
                errors.push(FieldError::new("at", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.bin.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.bin.is_some() {
                errors.push(FieldError::new("bin", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.data.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.data.is_some() {
                errors.push(FieldError::new("data", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.feeling.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.feeling.is_some() {
                errors.push(FieldError::new("feeling", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.code.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.code.is_some() {
                errors.push(FieldError::new("code", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 5 {
                errors.push(FieldError::new("code", "is longer than 5 characters"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Thing".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Thing>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
