}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Thing, values: &Values) {
    if let Some(value) = &values.id {
        entity.id = value.clone();
    }
    if let Some(value) = &values.tiny {
        entity.tiny = *value;
