    }
    if let Some(value) = &values.long_note {
        entity.long_note = value.clone();
    }
}

/// The values an update gives, by field.
fn given(changes: ThingChanges) -> Values {
    Values { tiny: changes.tiny.given(), small: changes.small.given(), medium: changes.medium.given(), num: changes.num.given(), big: changes.big.given(), price: changes.price.given(), r: changes.r.given(), d: changes.d.given(), flag: changes.flag.given(), born: changes.born.given(), opens: changes.opens.given(), at: changes.at.given(), changed: changes.changed.given(), bin: changes.bin.given(), blobby: changes.blobby.given(), data: changes.data.given(), feeling: changes.feeling.given(), code: changes.code.given(), note: changes.note.given(), long_note: changes.long_note.given(), ..Default::default() }
}

/// The Thing with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: Vec<u8>) -> Result<Thing, DomainError> {
    uow.things().find_by_id(id.clone()).await?.ok_or_else(|| DomainError::not_found("Thing", id))
}

