use rust_sql_ddl_mysql::entities::thing::Thing;
use rust_sql_ddl_mysql::unit_of_work::UnitOfWork;

/// A valid Thing that is not stored yet; n makes its unique values differ.
pub fn new_thing(n: i32) -> Thing {
    Thing {
        id: Some(vec![n as u8; 16]),
        tiny: Some((n) as i16),
        small: Some((n) as i16),
        medium: Some(n),
        num: Some(n),
        big: Some(i64::from(n)),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        r: Some((n) as f32 + 0.5),
        d: Some(f64::from(n) + 0.5),
        flag: Some(true),
        born: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        opens: Some(chrono::NaiveTime::from_hms_opt(12, (n % 60) as u32, 0).expect("a time")),
        at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time")),
        changed: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time")),
        bin: Some(vec![n as u8; 50]),
        blobby: Some(vec![n as u8]),
        data: Some(format!("{{\"n\": {n}}}")),
        feeling: Some("sad".to_string()),
        code: Some(format!("{:0>5}", n % 100000)),
        note: Some(format!("note-{n}")),
        long_note: Some(format!("longnote-{n}")),
        ..Default::default()
    }
}

/// A stored Thing.
pub async fn add_thing(uow: &dyn UnitOfWork, n: i32) -> Thing {
    let entity = new_thing(n);
    uow.things().insert(entity).await.expect("a stored Thing")
}

/// A valid Kind that is not stored yet; n makes its unique values differ.
pub fn new_kind(n: i32) -> Kind {
    Kind {
        code: Some(format!("code-{n}")),
        day: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        label: Some(format!("label-{n}")),
        ..Default::default()
    }
}

/// A stored Kind.
pub async fn add_kind(uow: &dyn UnitOfWork, n: i32) -> Kind {
    let entity = new_kind(n);
    uow.kinds().insert(entity).await.expect("a stored Kind")
}

/// A valid Order that is not stored yet; n makes its unique values differ.
pub fn new_order(n: i32) -> Order {
    Order {
        user: Some(format!("user-{n}")),
        group: Some(n),
        customer_name: Some(format!("customername-{n}")),
        class: Some(format!("class-{n}")),
        metadata: Some(format!("metadata-{n}")),
        date: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        time: Some(chrono::NaiveTime::from_hms_opt(12, (n % 60) as u32, 0).expect("a time")),
        text: Some(format!("text-{n}")),
        list: Some(format!("list-{n}")),
        str: Some(format!("str-{n}")),
        int: Some(n),
        due_date: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        closes_at: Some(chrono::NaiveTime::from_hms_opt(12, (n % 60) as u32, 0).expect("a time")),
        ..Default::default()
    }
}

/// A stored Order.
pub async fn add_order(uow: &dyn UnitOfWork, n: i32) -> Order {
    let entity = new_order(n);
    uow.order().insert(entity).await.expect("a stored Order")
}

/// A valid AuditEntry that is not stored yet; n makes its unique values differ.
pub fn new_audit_entry(n: i32) -> AuditEntry {
    AuditEntry {
        message: Some(format!("message-{n}")),
        ..Default::default()
    }
}

/// A stored AuditEntry, with the rows it points to.
pub async fn add_audit_entry(uow: &dyn UnitOfWork, n: i32) -> AuditEntry {
    let parent0 = add_order(uow, n).await;
    let mut entity = new_audit_entry(n);
    entity.order_id = parent0.id;
    uow.audit_entries().insert(entity).await.expect("a stored AuditEntry")
}

/// A valid Empty that is not stored yet; n makes its unique values differ.
pub fn new_empty(n: i32) -> Empty {
    Empty {
        note: Some(format!("note-{n}")),
        ..Default::default()
    }
}

/// A stored Empty.
pub async fn add_empty(uow: &dyn UnitOfWork, n: i32) -> Empty {
    let entity = new_empty(n);
    uow.empties().insert(entity).await.expect("a stored Empty")
}

