//! The repository of the "kinds" table, against the test database.

use rust_sql_ddl_mysql::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_kind(&uow, 1).await;
    let found = uow.kinds().find_by_code_and_day(stored.code.clone().expect("code is set"), stored.day.expect("day is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.code, found.code);
    assert_eq!(stored.day, found.day);
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_kind(&uow, 1).await;
    factories::add_kind(&uow, 2).await;
    let page = uow.kinds().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn stores_the_changes() {
    let (_turn, uow) = database::open().await;
    let mut stored = factories::add_kind(&uow, 1).await;
    stored.label = Some("changed".to_string());
    uow.kinds().update(stored.clone()).await.expect("an update");
    let found = uow.kinds().find_by_code_and_day(stored.code.clone().expect("code is set"), stored.day.expect("day is set")).await.expect("a read");
    assert_eq!(Some("changed".to_string()), found.and_then(|row| row.label));
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_kind(&uow, 1).await;
    uow.kinds().delete(&stored).await.expect("a delete");
    assert!(uow.kinds().find_by_code_and_day(stored.code.clone().expect("code is set"), stored.day.expect("day is set")).await.expect("a read").is_none());
}

