//! The service of the "kinds" table, on the in-memory repositories.

use rust_sql_ddl_mysql::common::Patch;
use rust_sql_ddl_mysql::errors::DomainError;
use rust_sql_ddl_mysql::services::kind::{KindChanges, KindService};
use rust_sql_ddl_mysql::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = KindService::new(uow.clone());
    let row = factories::new_kind(1);
    let created = service.create_kind(row).await.expect("a create");
    let found = service.get_kind(created.code.clone().expect("code is set"), created.day.expect("day is set")).await.expect("a read");
    assert_eq!(created.code, found.code);
    assert_eq!(created.day, found.day);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = KindService::new(uow.clone());
    let mut row = factories::new_kind(1);
    row.code = None;
    let error = service.create_kind(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["code"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = KindService::new(uow.clone());
    assert!(matches!(service.get_kind("missing".to_string(), chrono::NaiveDate::from_ymd_opt(1999, 1, 1).expect("a date")).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn changes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = KindService::new(uow.clone());
    let row = factories::new_kind(1);
    let created = service.create_kind(row.clone()).await.expect("a create");
    let updated = service.update_kind(created.code.clone().expect("code is set"), created.day.expect("day is set"), KindChanges { label: Patch::Set(Some("changed".to_string())), ..Default::default() }).await.expect("an update");
    assert_eq!(updated.label, Some("changed".to_string()));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = KindService::new(uow.clone());
    let row = factories::new_kind(1);
    let created = service.create_kind(row).await.expect("a create");
    service.delete_kind(created.code.clone().expect("code is set"), created.day.expect("day is set")).await.expect("a delete");
    assert!(matches!(service.get_kind(created.code.clone().expect("code is set"), created.day.expect("day is set")).await, Err(DomainError::NotFound { .. })));
}

