//! The repository of the "Order" table, against the test database.

use rust_sql_ddl_mysql::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_order(&uow, 1).await;
    let found = uow.order().find_by_id(stored.id.expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
    assert!(uow.order().find_by_customer_name(stored.customer_name.clone().expect("customer_name is set")).await.expect("a read").is_some());
    if stored.thing_id.is_some() {
        assert_eq!(1, uow.order().list_by_thing_id(stored.thing_id.clone().expect("thing_id is set")).await.expect("a read").len());
    }
    if stored.parent_id.is_some() {
        assert_eq!(1, uow.order().list_by_parent_id(stored.parent_id.expect("parent_id is set")).await.expect("a read").len());
    }
    if stored.kind_code.is_some() && stored.kind_day.is_some() {
        assert_eq!(1, uow.order().list_by_kind_code_and_kind_day(stored.kind_code.clone().expect("kind_code is set"), stored.kind_day.expect("kind_day is set")).await.expect("a read").len());
    }
}

#[tokio::test]
async fn lists_rows_by_key() {
