    factories::add_order(&uow, 1).await;
    factories::add_order(&uow, 2).await;
    let page = uow.order().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn stores_the_changes() {
    let (_turn, uow) = database::open().await;
    let mut stored = factories::add_order(&uow, 1).await;
    stored.user = Some("changed".to_string());
    uow.order().update(stored.clone()).await.expect("an update");
    let found = uow.order().find_by_id(stored.id.expect("id is set")).await.expect("a read");
    assert_eq!(Some("changed".to_string()), found.and_then(|row| row.user));
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_order(&uow, 1).await;
    uow.order().delete(&stored).await.expect("a delete");
    assert!(uow.order().find_by_id(stored.id.expect("id is set")).await.expect("a read").is_none());
