#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_thing(uow.as_ref(), 100).await;
    let parent1 = factories::add_order(uow.as_ref(), 100).await;
    let parent2 = factories::add_kind(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.thing_id = parent0.id.clone();
    row.parent_id = parent1.id;
    row.kind_code = parent2.code.clone();
    row.kind_day = parent2.day;
    let created = service.create_order(row).await.expect("a create");
    let found = service.get_order(created.id.expect("id is set")).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_thing(uow.as_ref(), 100).await;
    let parent1 = factories::add_order(uow.as_ref(), 100).await;
    let parent2 = factories::add_kind(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.thing_id = parent0.id.clone();
    row.parent_id = parent1.id;
    row.kind_code = parent2.code.clone();
    row.kind_day = parent2.day;
    row.user = None;
    let error = service.create_order(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["user"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn refuses_a_repeated_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_thing(uow.as_ref(), 100).await;
    let parent1 = factories::add_order(uow.as_ref(), 100).await;
    let parent2 = factories::add_kind(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.thing_id = parent0.id.clone();
    row.parent_id = parent1.id;
    row.kind_code = parent2.code.clone();
    row.kind_day = parent2.day;
    let first = service.create_order(row).await.expect("a create");
    let mut again = factories::new_order(2);
    again.thing_id = parent0.id.clone();
    again.parent_id = parent1.id;
    again.kind_code = parent2.code.clone();
    again.kind_day = parent2.day;
    again.customer_name = first.customer_name.clone();
    assert!(matches!(service.create_order(again).await, Err(DomainError::Conflict { .. })));
}

#[tokio::test]
async fn keeps_its_own_unique_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent0 = factories::add_thing(uow.as_ref(), 100).await;
    let parent1 = factories::add_order(uow.as_ref(), 100).await;
    let parent2 = factories::add_kind(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.thing_id = parent0.id.clone();
    row.parent_id = parent1.id;
    row.kind_code = parent2.code.clone();
    row.kind_day = parent2.day;
    let created = service.create_order(row.clone()).await.expect("a create");
    let updated = service.update_order(created.id.expect("id is set"), OrderChanges { customer_name: Patch::Set(created.customer_name.clone()), ..Default::default() }).await.expect("an update");
    assert_eq!(created.customer_name, updated.customer_name);
}

#[tokio::test]
async fn refuses_a_missing_parent() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = OrderService::new(uow.clone());
    let parent1 = factories::add_order(uow.as_ref(), 100).await;
    let parent2 = factories::add_kind(uow.as_ref(), 100).await;
    let mut row = factories::new_order(1);
    row.parent_id = parent1.id;
    row.kind_code = parent2.code.clone();
    row.kind_day = parent2.day;
    row.thing_id = Some(vec![255, 255]);
    let error = service.create_order(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert!(errors.iter().any(|error| error.field == "thing_id"));
}

